  rg_wf r -> (1 <= n)%nat ->
  (rg_lo r <= bv_unsigned (bdenot E (a_base a)) + a_off a)%Z ->
  (bv_unsigned (bdenot E (a_base a)) + a_off a + Z.of_nat n <= rg_hi r)%Z ->
